document.querySelectorAll('.copy').forEach(b=>b.addEventListener('click',async()=>{try{await navigator.clipboard.writeText(b.closest('.code-example').querySelector('code').textContent);b.textContent='Đã sao chép';setTimeout(()=>b.textContent='Sao chép',1800)}catch{b.textContent='Chọn mã để sao chép'}}));document.querySelector('#search').addEventListener('input',e=>{let q=e.target.value.toLocaleLowerCase('vi');document.querySelectorAll('aside nav a').forEach(a=>a.hidden=!a.textContent.toLocaleLowerCase('vi').includes(q))});addEventListener('scroll',()=>{let h=document.documentElement;document.querySelector('.progress').style.width=(h.scrollTop/(h.scrollHeight-h.clientHeight)*100)+'%'});
const quiz=document.querySelector('#quiz');quiz.addEventListener('submit',e=>{e.preventDefault();const rows=[...quiz.querySelectorAll('fieldset')];let correct=0,answered=0;rows.forEach(row=>{const selected=row.querySelector('input:checked');const ok=selected&&selected.value===row.dataset.answer;if(selected)answered++;if(ok)correct++;row.classList.toggle('answer-correct',!!ok);row.classList.toggle('answer-wrong',!ok);const feedback=row.querySelector('.feedback');feedback.hidden=false;feedback.textContent=(ok?'Đúng. ':selected?'Chưa đúng. ':'Chưa trả lời. ')+feedback.dataset.explanation;});document.querySelector('#score').textContent=`Kết quả: ${correct}/${rows.length} câu đúng · Đã trả lời ${answered}/${rows.length} câu.`;});quiz.querySelectorAll('.feedback').forEach(p=>p.dataset.explanation=p.textContent);quiz.addEventListener('reset',()=>{quiz.querySelectorAll('fieldset').forEach(row=>row.classList.remove('answer-correct','answer-wrong'));quiz.querySelectorAll('.feedback').forEach(p=>p.hidden=true);document.querySelector('#score').textContent='';});

const baseArray=[-2,-1,0,1,2,3];
const operations={original:{values:baseArray,code:'a = np.array([-2, -1, 0, 1, 2, 3])',caption:'6 phần tử · Thay đổi phép toán, quan sát kết quả.'},double:{values:baseArray.map(x=>x*2),code:'a * 2',caption:'Nhân từng phần tử với 2 — không cần vòng lặp.'},square:{values:baseArray.map(x=>x*x),code:'a ** 2',caption:'Bình phương từng phần tử. Các giá trị đều không âm.'},positive:{values:baseArray.filter(x=>x>0),code:'a[a > 0]',caption:'Mặt nạ boolean chỉ giữ 3 phần tử lớn hơn 0.'}};
document.querySelectorAll('[data-op]').forEach(button=>button.addEventListener('click',()=>{const operation=operations[button.dataset.op];document.querySelectorAll('[data-op]').forEach(b=>b.setAttribute('aria-pressed',String(b===button)));document.querySelector('#lab-code').textContent=operation.code;document.querySelector('#lab-caption').textContent=operation.caption;const values=document.querySelector('#array-values');values.replaceChildren(...operation.values.map(value=>{const span=document.createElement('span');span.textContent=value;return span;}));}));
const sectionLinks=[...document.querySelectorAll('aside nav a')];
if('IntersectionObserver' in window){const observer=new IntersectionObserver(entries=>{const visible=entries.filter(entry=>entry.isIntersecting).sort((a,b)=>a.boundingClientRect.top-b.boundingClientRect.top);if(!visible.length)return;const id=visible[0].target.id;sectionLinks.forEach(link=>{const active=link.hash==='#'+id;link.classList.toggle('is-active',active);if(active)link.setAttribute('aria-current','location');else link.removeAttribute('aria-current');});},{rootMargin:'-90px 0px -55% 0px',threshold:0});document.querySelectorAll('article h2[id],article h3[id],#exercises').forEach(section=>observer.observe(section));}
